//! Thread row context menu (RS-090, refs/interactions/s002.json): a right-click on a Recents
//! row calls `electronBridge.showContextMenu`, native in Electron, drawn here like the
//! transcript link menu (`thread/menu.rs`): the recorded items, order, accelerators and
//! submenus. `Pin` reads `Unpin` on a pinned row and `Mark as unread` reads `Mark as read` on
//! an unread one [INFERENCE: only a plain row was recorded].
use super::*;
use gpui::{Anchor, FocusHandle, KeyDownEvent, Point, Role, anchored, deferred};

/// One item as the original passes it to `showContextMenu`: id, label, Electron accelerator,
/// 16 px icon (its svg) and submenu. A separator has an empty label.
pub(super) struct Item {
    id: &'static str,
    label: &'static str,
    accelerator: Option<&'static str>,
    icon: Option<&'static [u8]>,
    submenu: &'static [Item],
}

const ROW: f32 = 28.5625;
const SEPARATOR: f32 = 9.;
const WIDTH: f32 = 220.;

pub(super) struct ThreadMenu {
    thread: String,
    position: Point<Pixels>,
    /// The active top-level item; `sub` is its open submenu's active item.
    active: Option<usize>,
    sub: Option<Option<usize>>,
    focus: FocusHandle,
    return_focus: Option<FocusHandle>,
}

impl Item {
    fn is_separator(&self) -> bool {
        self.label.is_empty()
    }

    /// `CmdOrCtrl+Alt+R` as macOS shows it: `⌥⌘R`.
    fn keys(&self) -> Option<String> {
        let (mods, key) = self.accelerator?.rsplit_once('+')?;
        let glyphs = [
            ("Control", "⌃"),
            ("Alt", "⌥"),
            ("Shift", "⇧"),
            ("CmdOrCtrl", "⌘"),
        ]
        .into_iter()
        .filter(|(m, _)| mods.split('+').any(|x| x == *m))
        .map(|(_, g)| g)
        .collect::<String>();
        Some(glyphs + key)
    }
}

